const activeTasks=()=>tasks.filter(t=>!t.done&&!t.chatOnly);
function taskActions(t){if(t.done)return [];if(t.id==='order')return [t.negotiation==='agreed'?'确认接单':'沟通改价'];if(t.contactPending)return ['确认沟通'];if(t.flow)return flowActions(t);if(t.day>today)return ['联系乘客'];return t.actions.filter(a=>a!=='出车准备'||t.id==='prepare')}
function completeTask(t,reply){if(t.done)return;if(reply)add('ai',reply);t.done=true;t.status='已完成';t.completedAt=new Date().toISOString();goBack();renderTasks();refreshReviewSurfaces();const list=$('#task-list');savedScroll=Math.min(savedScroll,Math.max(0,list.scrollHeight-list.clientHeight));list.scrollTop=savedScroll;current=visibleTask();toast('任务已完成，已移入历史任务')}

const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function buttonLabel(text){return ({'确认沟通':'我已了解','调整价格':'沟通改价','完成行前确认':'确认完成','前往接驾点':'前往接驾','前往目的地':'开始送达'})[text]||text}
function taskActionCompleted(t,action){return t.done||(action==='联系乘客'&&t.contactConfirmed)||(action==='出车准备'&&preparedDays.has(t.day))}
function card(t,compact=false){return `<article class="task-card" data-id="${t.id}"><h2 class="task-title"><img src="icons/${t.icon}.svg" alt=""><span>${esc(t.time)}${t.id==='prepare'?'':' '}${esc(t.name)}</span></h2><div class="details">${t.id.startsWith('custom-')?'':t.id==='prepare'?`<p class="prep-intro">上传车辆照与个人照<br>确认车况、证照与随车物品</p>`:compact?`<div>${esc(t.customer)} · ${esc(t.from)}</div>`:`<div class="customer">${esc(t.customer)}<a href="tel:${t.phone}">${t.phone}</a></div><p class="route">${esc(t.from)}→${esc(t.to.replace(/机场\s+T/g,'机场T'))}</p>`}<p class="advice">${esc(t.flow?rideSteps[t.flowIndex].hint(t):t.contactPending?'乘客已回复，请确认沟通结果':t.advice)}</p></div>${compact?'':`<div class="actions">${taskActions(t).map((a,i)=>`<button class="action ${i===taskActions(t).length-1?'primary':''}" data-task="${t.id}" data-action="${a}" ${taskActionCompleted(t,a)?'disabled':''}>${buttonLabel(a)}</button>`).join('')}</div>`}${!compact&&t.id==='order'?`<div class="task-meta">当前报价￥${t.price}</div>`:''}</article>`}
function needsTaskConversation(t){if(t.id==='prepare'||t.done)return false;return !!(t.contactPending||t.awaitingPrice||t.flow||/沟通|联系|议价|确认|需求|安排/.test([t.name,t.advice,...taskActions(t)].join(' ')))}
function browseComposer(t){if(!needsTaskConversation(t))return '';return `<div class="composer browse-composer" data-browse-task="${t.id}"><button class="icon-button" data-browse-mode="add" aria-label="快捷指令"><img src="icons/plus.svg" alt=""></button><button class="browse-input" data-browse-mode="input" aria-label="告诉我你想做什么">告诉我你想做什么</button><button class="icon-button" data-browse-mode="mic" aria-label="语音输入"><img src="icons/microphone.svg" alt=""></button></div>`}
function renderTasks(){renderHomeIntro(); const list=$('#task-list'),position=list.scrollTop;const active=homeTasks();$('#task-summary').textContent=`今日任务，共 ${active.length} 件`;list.innerHTML=active.map((t,i)=>`<section class="task-page" aria-label="任务 ${i+1}，共 ${active.length} 项">${homeCard(t)}${browseComposer(t)}</section>`).join('')||'<div class="empty-tasks"><img src="icons/check-circle.svg" alt=""><h2>辛苦了，歇一歇吧</h2><p>喝口水，活动一下肩颈。<br>照顾好自己，再从容出发。</p></div>';list.scrollTop=position; queueTaskMotion(); if(open)$('#context').innerHTML=card(current,true); }
