function updateHeader(){const detail=open||conversationPage;$('#app').classList.toggle('profile-mode',activeTab==='profile'&&!detail&&!allTasksOpen);if($('#profile-page'))$('#profile-page').hidden=activeTab!=='profile'||detail||allTasksOpen;$('#app').classList.toggle('home-design',activeTab==='home'&&!detail&&!allTasksOpen);$('#header-new-chat').hidden=activeTab!=='ai'||detail;$('#app').classList.toggle('conversation-page',detail);$('#app').classList.toggle('task-from-all',open&&taskFromAll);$('#app').classList.remove('history-conversation');$('#menu').hidden=activeTab!=='ai'&&!allTasksOpen&&!detail;$('#intercom').hidden=activeTab!=='ai'||open||conversationPage;$('#sound').hidden=!detail&&(activeTab==='home'||activeTab==='review');$('#close').hidden=true;$('#page-title').textContent=allTasksOpen?'全部任务':open?'任务对话':conversationPage?'复盘对话':activeTab==='review'?'看板':activeTab==='ai'?'智能助手':activeTab==='profile'?'我的':'任务';$('#menu img').src=allTasksOpen||detail?'icons/arrow-left.svg':'icons/list.svg';$('#menu').setAttribute('aria-label',detail?'返回上一页':allTasksOpen?(activeTab==='profile'?'返回我的主页':'返回看板'):'历史对话')}
function syncOverlay(){syncInquiryHeader();updateNavIcons();const drawer=$('#history-drawer'),modal=$('#utility'),layer=modal.open?modal:drawer.open?drawer:null;$('#overlay-scrim').hidden=!layer||(modal.classList.contains('new-task-dialog')||modal.classList.contains('voice-dialog'))&&modal.open;for(const selector of ['.statusbar','header','.workspace','footer'])$(selector).inert=!!layer;for(const el of [drawer,modal]){el.setAttribute('aria-modal','true');el.inert=el!==layer}if(layer)requestAnimationFrame(()=>[...layer.querySelectorAll('button,input')].find(el=>el.getClientRects().length&&!el.disabled)?.focus({preventScroll:true}))}
function goBack(){if(allTasksOpen&&!$('#utility').open&&!$('#history-drawer').open){closeAllTasks();return;}if($('#utility').classList.contains('voice-dialog'))stopIntercom();const previous=navigationStack.pop();restoring=true;$('#utility').close();$('#history-drawer').close();syncOverlay();if(open)closeChat();conversationPage=false;if(previous){conversationPage=!!previous.conversationPage;reviewConversation=reviewConversations.find(c=>c.id===previous.reviewId)||null;aiTask=tasks.find(t=>t.id===previous.aiTaskId)||null;applyPageSurface(previous.activeTab||'home',!!previous.allTasksOpen);if(previous.allTasksOpen){allTasksPage.innerHTML=allTasksBody(previous.allFilter);allTasksPage.scrollTop=previous.allScroll;}if($('.review-feed'))$('.review-feed').scrollTop=previous.reviewScroll;savedScroll=previous.savedScroll;$('#task-list').scrollTop=previous.scroll;current=tasks.find(t=>t.id===previous.taskId)||visibleTask();historyConversation=previous.historyConversation;taskFromAll=!!previous.taskFromAll;if(previous.open&&current){showTask(current);savedScroll=previous.savedScroll;requestAnimationFrame(()=>{$('#messages').scrollTop=previous.chatScroll})}if(previous.drawer){showHistory();$('#history-list').scrollTop=previous.drawerScroll}if(previous.utility){utility(previous.utility.title,previous.utility.body);$('#utility').className=previous.utility.className;for(const field of previous.utility.fields){const el=[...$('#utility').querySelectorAll('input,textarea')].find(x=>x.name===field.name);if(el)el.value=field.value}}}if(previous){$('#input').value=previous.input||'';updateSend()}restoring=false;if(activeTab==='ai'&&!open)renderAI();updateHeader();syncOverlay()}
$('#overlay-scrim').onclick=goBack;
document.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();if(allTasksOpen||open||conversationPage||$('#utility').open||$('#history-drawer').open)goBack()}if(e.key==='Tab'){const layer=$('#utility').open?$('#utility'):$('#history-drawer').open?$('#history-drawer'):null;if(!layer)return;const controls=[...layer.querySelectorAll('button,input,textarea,a[href]')].filter(x=>!x.disabled);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
if(window.visualViewport){visualViewport.addEventListener('resize',()=>{if(window.innerWidth<=430)$('#app').style.height=Math.min(844,visualViewport.height)+'px';else $('#app').style.removeProperty('height')})}
new ResizeObserver(()=>{if(open){$('#chat').style.top=($('#context').offsetTop+$('#context').offsetHeight+20)+'px'}}).observe($('#context'));
renderTasks();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_task_processing',description:'在工作台展开指定任务的 AI 操作面板，不执行订单操作。',inputSchema:{type:'object',properties:{taskId:{type:'string',enum:tasks.map(t=>t.id)}},required:['taskId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{const t=tasks.find(t=>t.id===input?.taskId);if(!t)throw new Error('Unknown task');showTask(t);return{taskId:t.id,status:t.status,panelOpen:open}}})).catch(()=>{})}catch{}}

// Review uses the same live task records, with conversations isolated from workbench tasks.
const reviewSection=document.createElement('section');reviewSection.id='review';reviewSection.hidden=true;$('.workspace').append(reviewSection);
function taskDeadline(t){if(t.dueAt)return new Date(t.dueAt).getTime();const time=t.time.match(/\d{2}:\d{2}/)?.[0]||'23:59';return new Date(`${t.day}T${time}:00`).getTime()}
function taskState(t){return t.done?'已完成':Date.now()>taskDeadline(t)?'逾期':'待办'}
function reviewData(){const all=tasks.filter(t=>!t.chatOnly),late=all.filter(t=>taskState(t)==='逾期'),timely=all.filter(t=>t.done&&t.completedAt&&new Date(t.completedAt).getTime()<=taskDeadline(t)),customers=[...new Set(all.map(t=>t.customer).filter(Boolean))],orders=all.filter(t=>t.price!=null);return {all,late,timely,customers,orders}}
function taskReviewAdvice(){const d=reviewData();return d.late.length?`当前有 ${d.late.length} 项逾期任务，建议优先处理“${d.late[0].name}”，确认延误原因后再安排后续任务。` : d.all.some(t=>!t.done)?'当前没有逾期任务。建议先完成出车准备，再按预约时间处理接送与客户沟通，提前确认明日行程。':'当前任务均已完成，建议回顾客户反馈，为下一次服务做好准备。'}
function reviewCard(title,icon,body,index){const advice=body.match(/<div class="review-advice">[\s\S]*?<\/p><\/div>/)?.[0]||'';body=body.replace(advice,'')+reviewShortcuts(title);const hint=index<3?'向上滑动，查看'+(index===1?'客户':'订单')+'复盘':'向下滑动，回看客户与任务';return `<section class="review-page" aria-label="${title}复盘" data-review-hint="${hint}"><article class="review-card"><div class="review-card-heading"><h2><img src="icons/${icon}.svg" alt="">${title}</h2></div>${body}</article></section>`}
let reviewMotionObserver;
function bindReviewMotion(){reviewMotionObserver?.disconnect();const feed=$('.review-feed'),hint=$('.review-swipe-fixed');if(!feed||!hint)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let frame=0,hintTimer=0;const pages=[...feed.querySelectorAll('.review-page')];const nearest=()=>pages.reduce((best,page)=>Math.abs(feed.scrollTop-page.offsetTop)<Math.abs(feed.scrollTop-best.offsetTop)?page:best,pages[0]);const update=()=>{frame=0;if(reduced)return;const top=feed.getBoundingClientRect().top,height=feed.clientHeight||1;pages.forEach(page=>{const distance=(page.getBoundingClientRect().top-top)/height,progress=Math.min(1,Math.abs(distance)),eased=progress*progress*(3-2*progress);page.style.setProperty('--review-shift',`${(distance*20).toFixed(1)}px`);page.style.setProperty('--review-scale',(1-.04*eased).toFixed(4));page.style.setProperty('--review-opacity',(1-.18*eased).toFixed(3))})};const queue=()=>{if(!frame)frame=requestAnimationFrame(update)};feed.addEventListener('scroll',()=>{hint.classList.add('is-scrolling');clearTimeout(hintTimer);queue();hintTimer=setTimeout(()=>{hint.textContent=nearest().dataset.reviewHint;hint.classList.remove('is-scrolling')},110)},{passive:true});reviewMotionObserver=new ResizeObserver(queue);reviewMotionObserver.observe(feed);hint.textContent=nearest().dataset.reviewHint;update()}
function renderReview(){

 const d=reviewData(),done=d.all.filter(t=>t.done).length,pending=d.all.length-done-d.late.length;
 const segments=[{label:'及时完成',value:d.timely.length,color:'#627BFF'},{label:'逾期任务',value:d.late.length,color:'#FF8B62'},{label:'待办任务',value:pending,color:'#DDE0E6'},{label:'逾期完成',value:done-d.timely.length,color:'#FFC857'}];
 let sum=0;const stops=segments.map(x=>{const start=sum;sum+=d.all.length?x.value/d.all.length*100:0;return `${x.color} ${start}% ${sum}%`}).join(',');
 const taskChart=`<div class="task-chart"><div class="review-donut" role="img" aria-label="任务总数 ${d.all.length}，及时完成 ${d.timely.length}，逾期 ${d.late.length}，待办 ${pending}，逾期完成 ${done-d.timely.length}" style="--ring:conic-gradient(${d.all.length?stops:'#e4e7f2 0% 100%'})"><div><strong>${d.all.length}</strong><span>任务总数</span></div></div><div class="chart-legend">${segments.filter((x,i)=>i<3||x.value).map(x=>`<div><span><i style="background:${x.color}"></i>${x.label}</span><b>${x.value}<small>项</small></b></div>`).join('')}</div></div>`;
 const customerChart=customerMetrics();
 const orderChart=orderMetrics();
 reviewSection.innerHTML=`<div class="review-feed">${reviewCard('任务','clipboard-text-outline',`${taskChart}<div class="review-advice"><span>AI 建议</span><p>${taskReviewAdvice()}</p></div>`,1)}${reviewCard('客户','user',`${customerChart}<div class="review-advice"><span>AI 建议</span><p>提前确认今日接驾位置与行李需求，并与明日出游客户沟通休息和用餐安排。</p></div>`,2)}${reviewCard('订单','check-circle',`${orderChart}<div class="review-advice"><span>AI 建议</span><p>${tasks.find(t=>t.id==='order').done?'议价订单已确认，建议核对接送时间，提前安排车辆。':'王静怡的订单仍需确认报价，建议先完成议价沟通，再确认接单。'}</p></div>`,3)}</div><p class="review-swipe review-swipe-fixed" aria-hidden="true">向上滑动，查看客户复盘</p>`;
 bindReviewMotion();
}
function switchTab(tab){if(allTasksOpen)closeAllTasks();if(open)closeChat();conversationPage=false;navigationStack.length=0;if(tab==='ai'){reviewConversation=null;aiTask=null}applyPageSurface(tab,false);$('#input').value='';updateSend();if(tab==='review')renderReview();else if(tab==='home')renderTasks();else if(tab==='profile')renderProfile();else renderAI();updateHeader()}
$('#schedule').setAttribute('aria-label','看板');$('#schedule').onclick=()=>switchTab('review');$('#home').onclick=()=>switchTab('home');$('#ai-tab').onclick=()=>switchTab('ai');
function taskDescription(t){if(t.description)return t.description;if(t.id==='prepare')return '上传车辆照和个人照，确认行驶证照、能源车况、乘用物品及司机状态。';if(t.id==='airport')return `接${t.customer}从${t.from}前往${t.to}，提前确认落地出口与行李数量。`;if(t.id==='contact')return `联系${t.customer}确认贵阳北站碰面位置，提前安排两件大行李的存放空间。`;if(t.id==='order')return `与${t.customer}沟通机场接送报价，客户期望 ¥${t.requestedPrice}，达成一致后确认接单。`;if(t.id==='tour')return `确认陈志远一家黄果树出游安排，提前沟通老人和儿童的休息、用餐需求。`;return t.advice}
function allTasksBody(filter){const rank={'逾期':0,'待办':1,'已完成':2},all=[...reviewData().all].sort((a,b)=>rank[taskState(a)]-rank[taskState(b)]),shown=all.filter(t=>filter==='全部'||taskState(t)===filter);return `<div class="task-filters" role="tablist" aria-label="任务状态">${['全部','逾期','待办','已完成'].map(f=>`<button role="tab" aria-selected="${f===filter}" data-task-filter="${f}">${f}</button>`).join('')}</div>${shown.map(t=>`<button class="utility-row task-list-row" data-review-task="${t.id}"><span class="task-row-heading"><strong>${esc(t.name)}</strong><span class="task-state ${t.done?'done':taskState(t)==='逾期'?'late':''}">${taskState(t)}</span></span><span class="task-row-description">${esc(taskDescription(t))}</span><span class="task-row-meta"><span>${esc(t.day)} · ${esc(t.time)}</span><span>${t.done?'查看记录':'去处理'} →</span></span></button>`).join('')||'<p class="review-empty">暂无'+filter+'任务</p>'}`}
function showReviewHistory(){if(!restoring)rememberPage();$('#utility').close();$('#history-title').textContent='复盘历史对话';$('#history-close').setAttribute('aria-label','关闭历史对话');$('#new-task').hidden=true;$('#history-tabs').hidden=true;$('#history-list').innerHTML=[...reviewConversations].reverse().map(c=>`<button class="history-row" data-review-history="${c.id}"><span class="history-icon"><img src="icons/chat-circle-dots.svg" alt=""></span><span class="history-copy"><strong>${esc(c.title)}</strong><small>${esc(c.date)} · ${c.messages.filter(m=>m.role==='user').length} 轮对话</small></span></button>`).join('')||'<p class="review-empty">暂无复盘对话<br>在底部向 AI 提问，开始第一次复盘</p>';$('#history-drawer').show();syncOverlay()}
function reviewReply(text){const business=businessReply(text);if(business)return business;const d=reviewData();if(/客户|乘客/.test(text))return `当前共 ${d.customers.length} 位客户。建议提前确认张晓雯的接驾位置、李明轩的行李需求，并与陈志远确认明日行程中的休息和用餐安排。`;if(/订单|报价|收入/.test(text))return `当前关联 ${d.orders.length} 笔订单，报价合计 ¥${d.orders.reduce((n,t)=>n+t.price,0)}，不代表已结算收入。${tasks.find(t=>t.id==='order').done?'王静怡的订单已确认。':'建议优先与王静怡沟通报价，达成一致后确认接单。'}`;return `当前共有 ${d.all.length} 项任务，及时完成 ${d.timely.length} 项，逾期 ${d.late.length} 项。${taskReviewAdvice()}${/任务|复盘|完成|逾期|建议/.test(text)?'':'你也可以继续问我任务完成情况、客户沟通或订单报价。'}`}
function submitReview(text){submitAI(text)}
function renderReviewChat(){renderAI()}
$('#history-list').addEventListener('click',e=>{const row=e.target.closest('[data-review-history]');if(!row)return;reviewConversation=reviewConversations.find(c=>c.id===row.dataset.reviewHistory);goBack();renderReviewChat()});
document.addEventListener('click',e=>{if(e.target.closest('[data-all-tasks]'))openAllTasks();const filter=e.target.closest('[data-task-filter]');if(filter){$('#all-tasks-page').innerHTML=allTasksBody(filter.dataset.taskFilter);$('#all-tasks-page [aria-selected="true"]').focus();}const question=e.target.closest('[data-review-question]');if(question){goBack();submitReview(question.dataset.reviewQuestion)}if(e.target.closest('[data-review-back],[data-review-new]')){reviewConversation=null;renderReview()}const task=e.target.closest('[data-review-task]');if(task)showTask(tasks.find(t=>t.id===task.dataset.reviewTask));});

function updateNavIcons(){const selected=activeTab==='profile'?'profile':activeTab==='review'?'schedule':activeTab==='ai'?'ai-tab':'home';for(const [id,icon] of [['home','nav-task'],['schedule','nav-board'],['ai-tab','nav-chat'],['profile','nav-profile']]){const button=$('#'+id);button.classList.toggle('selected',id===selected);button.setAttribute('aria-current',id===selected?'page':'false');button.querySelector('img').src=`icons/${icon}.png`}}
const allTasksPage=document.createElement('section');allTasksPage.id='all-tasks-page';allTasksPage.hidden=true;allTasksPage.setAttribute('aria-label','全部任务列表');$('.workspace').append(allTasksPage);
function openAllTasks(){allTasksOpen=true;$('#task-list').hidden=true;aiSection.hidden=true;$('#app').classList.add('secondary-page');reviewSection.hidden=true;allTasksPage.hidden=false;allTasksPage.innerHTML=allTasksBody('全部');updateHeader();$('#menu').focus()}
function closeAllTasks(){allTasksOpen=false;$('#app').classList.remove('secondary-page');allTasksPage.hidden=true;applyPageSurface(activeTab,false);updateHeader();$('[data-all-tasks]')?.focus()}
updateNavIcons();

function applyPageSurface(tab,allOpen){activeTab=tab;allTasksOpen=allOpen;$('#app').classList.toggle('review-mode',tab==='review');$('#app').classList.toggle('ai-mode',tab==='ai');$('#app').classList.toggle('secondary-page',allOpen);$('#task-list').hidden=tab!=='home'||allOpen;$('#task-summary').hidden=tab!=='home'||allOpen;reviewSection.hidden=tab!=='review'||allOpen;aiSection.hidden=tab!=='ai'||open;allTasksPage.hidden=!allOpen;$('#input').placeholder=tab==='review'?'和 AI 聊聊本次复盘':'告诉我你想做什么';updateNavIcons()}
function refreshReviewSurfaces(){if(activeTab!=='review')return;const scroll=$('.review-feed')?.scrollTop||0;renderReview();if($('.review-feed'))$('.review-feed').scrollTop=scroll;if(allTasksOpen){const filter=$('#all-tasks-page [aria-selected="true"]')?.dataset.taskFilter||'全部',position=allTasksPage.scrollTop;allTasksPage.innerHTML=allTasksBody(filter);allTasksPage.scrollTop=position}}

function taskOpening(t){const description=taskDescription(t);if(t.done)return description+'\n这项任务已完成，可在下方查看处理记录。';const advice=t.id==='contact'?'建议先联系乘客，确认碰面位置和行李需求。':t.id==='airport'?'建议先确认车辆出车准备，再开始出发；接近和到达接驾点时，我会协助提醒乘客。':t.id==='prepare'?'建议在首次出车前上传两张照片并完成出车确认。':t.id==='order'?'建议先沟通报价，达成一致后再确认接单。':t.id==='tour'?'建议先联系乘客，确认集合时间、同行人员和行李需求。':'建议先整理处理要求，处理后记录结果并完成任务。';return description+'\n'+(taskState(t)==='逾期'?'这项任务已逾期，请优先处理。':'')+advice}
function taskChatActions(t,enabled=true,actions=taskActions(t)){return actions.length?`<div class="chat-task-actions">${actions.map(a=>`<button data-action="${esc(a)}" data-task="${t.id}" ${!enabled||taskActionCompleted(t,a)?'disabled':''}>${buttonLabel(a)}</button>`).join('')}</div>`:''}
function introActions(m,msgs){return taskChatActions(current,!msgs.some(x=>x.role==='user'),m.extra||[])}

function syncInquiryHeader(){let controls=$('#inquiry-header-controls');if(!controls){controls=document.createElement('div');controls.id='inquiry-header-controls';controls.innerHTML='<button class="icon-button" data-header-sound aria-label="开启语音播报"><img src="icons/speaker-slash.svg" alt=""></button><button class="icon-button" data-header-intercom aria-label="打开对讲"><img src="icons/walkie-talkie.svg" alt=""></button><button class="capsule" data-header-more aria-label="微信状态与更多选项"><img src="icons/dots-three.svg" alt=""><i></i><img src="icons/record.svg" alt=""></button>';$('#utility .dialog-head').append(controls);controls.addEventListener('click',e=>{if(e.target.closest('[data-header-intercom]'))openIntercom();if(e.target.closest('[data-header-sound]')){$('#sound').click();syncInquiryHeader()}if(e.target.closest('[data-header-more]'))$('#more').click()})}controls.hidden=!$('#utility').classList.contains('new-task-dialog');controls.querySelector('[data-header-intercom]').hidden=activeTab!=='ai';const sound=controls.querySelector('[data-header-sound]');sound.setAttribute('aria-label',muted?'开启语音播报':'关闭语音播报');sound.querySelector('img').src=`icons/${muted?'speaker-slash':'speaker-high'}.svg`}

// Unified AI workspace. Task records remain shared with the workbench.
const aiSection=document.createElement('section');aiSection.id='ai-page';aiSection.hidden=true;$('.workspace').append(aiSection);
let aiTask=null;
function reviewShortcuts(type){const late=reviewData().late[0];const suggestions=type==='任务'?[late?`优先处理${late.name}，梳理后续安排`:'梳理待办任务，安排处理顺序','回顾已完成任务，找出改进点']:type==='客户'?['排查黄小西客户流失原因','向高客单、高复购客户推送Q4出行计划']:['成交额为什么下降','下月增长机会'];return `<div class="review-advice review-shortcuts"><span>AI建议</span>${[...suggestions,'想换个思路，和 AI 聊聊'].map((q,i)=>`<button data-ai-shortcut="${esc(q)}" data-ai-type="${type}" data-free="${i===2}"><span>${esc(q)}</span><span aria-hidden="true">↗</span></button>`).join('')}</div>`}
function newAIChat(){conversationPage=false;navigationStack.length=0;$('#input').placeholder='告诉我你想做什么';if(activeTab!=='ai')switchTab('ai');if(open)closeChat();reviewConversation=null;aiTask=null;$('#input').value='';updateSend();renderAI();updateHeader()}
function renderAI(){if(activeTab!=='ai')return;aiSection.hidden=open;if(open)return;const c=reviewConversation,t=aiTask;const messages=c?.messages||(t?histories.get(t.id):[]);aiSection.innerHTML=`<div class="review-chat">${messages.length?`<div class="messages" role="log" aria-live="polite">${messages.map(m=>`<div class="message ${m.role}"><div class="bubble">${esc(m.text)}</div></div>`).join('')}</div>`:`<div class="ai-welcome"><h2>今天想先聊什么？</h2></div><div class="ai-recommendations"><h3>为你推荐</h3><div class="ai-prompt-list"><button data-ai-prompt="帮我梳理今天的任务安排">帮我梳理今天的任务安排 ↗</button><button data-ai-prompt="明天黄果树行程有几人，几件行李？">查询明日行程的乘客与行李 ↗</button></div></div>`}</div>`;const box=aiSection.querySelector('.messages');if(box)box.scrollTop=box.scrollHeight}
function submitAI(text){text=text.trim();if(!text)return;if(activeTab==='review'){startReviewChat(/订单|报价|收入/.test(text)?'订单':/客户|乘客/.test(text)?'客户':'任务',text);return}if(activeTab!=='ai')switchTab('ai');if(reviewConversation){reviewConversation.messages.push({role:'user',text},{role:'ai',text:reviewReply(reviewConversation.type+'：'+text)});}else{if(!aiTask){aiTask={id:'chat-'+Date.now(),chatOnly:true,day:today,time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),name:summarizeTask(text).name,icon:'chat-circle-dots',status:'进行中',actions:[],advice:text};tasks.push(aiTask);histories.set(aiTask.id,[])}histories.get(aiTask.id).push({role:'user',text});const reply=answerConversation(text,aiTask);histories.get(aiTask.id).push({role:'ai',text:reply});}$('#input').value='';updateSend();renderAI()}
function startReviewChat(type,text,free=false){rememberPage();conversationPage=true;applyPageSurface('ai',false);aiTask=null;reviewConversation={id:'review-'+Date.now(),type:'复盘-'+type,title:text.slice(0,26),date:new Date().toLocaleString('zh-CN',{hour12:false}),messages:[]};reviewConversations.push(reviewConversation);reviewConversation.messages.push({role:'user',text},{role:'ai',text:free?`我们一起换个思路。关于${type}，你希望调整哪部分建议，或有什么实际情况需要补充？`:reviewReply(type+'：'+text)});renderAI();updateHeader();$('#input').placeholder=free?'说说你的想法或实际情况':'继续聊聊这条建议'}
document.addEventListener('click',e=>{const shortcut=e.target.closest('[data-ai-shortcut]');if(shortcut)startReviewChat(shortcut.dataset.aiType,shortcut.dataset.aiShortcut,shortcut.dataset.free==='true');if(e.target.closest('[data-ai-new]'))newAIChat();const prompt=e.target.closest('[data-ai-prompt]');if(prompt)submitAI(prompt.dataset.aiPrompt)});
updateHeader();

// Local context policy: structured checks stay in the checklist; communication gets AI assistance.
function todayTaskAdvice(){const day=localDate(new Date()),list=tasks.filter(t=>!t.chatOnly&&t.day===day),pending=list.filter(t=>!t.done),completed=list.filter(t=>t.done);if(!pending.length)return `今天的 ${list.length} 项任务都已完成。建议检查车内是否有遗留物品、补齐随车用品，再确认明日预约。`;const prep=pending.find(t=>t.id==='prepare'),scheduled=pending.filter(t=>t.id!=='prepare').sort((a,b)=>taskDeadline(a)-taskDeadline(b));const tips=scheduled.map(t=>{const late=taskState(t)==='逾期'?'（预约时间已过，请先确认实际进度）':'';let advice=t.flow?`当前${t.status}，下一步${rideSteps[t.flowIndex].action}。`:t.id==='airport'?`从${t.from}接${t.customer}去${t.to}；提前确认航班出口和到达时间，结合实际路况安排出发。`:t.id==='contact'?`联系${t.customer}确认${t.from}的碰面位置，核对两件大行李的存放需求。`:t.id==='order'?t.negotiation==='agreed'?`已达成 ¥${t.price} 的报价，下一步确认接单。`:`与${t.customer}确认报价：当前 ¥${t.price}，客户期望 ¥${t.requestedPrice}。达成一致后再确认接单。`:taskDescription(t);return `${t.time} ${t.name}${late}：${advice}`});const next=tasks.find(t=>!t.chatOnly&&!t.done&&t.day>day);return [`今天还有 ${pending.length} 项待处理，已完成 ${completed.length} 项。建议按以下顺序安排：`,prep?'先上传车辆照与个人照，确认车况、证照、随车物品及司机状态后再出发。':'出车准备已完成，接下来按预约时间衔接各项任务。',...tips,next?`今天的任务安排妥当后，可提前沟通${next.time}的${next.name}，确认老人和儿童的休息、用餐需求。`:''].filter(Boolean).join('\n\n')}
$('#header-new-chat').onclick=newAIChat;

// Illustrative business metrics, separate from today's operational task records.
const businessMetrics={customers:120,convertedCustomers:48,channels:[['黄小西',60],['私域',42],['其它',18]],segments:[['企业',30],['高端',24],['亲子',42],['其它',24]],revenue:[['出行服务',30720],['佣金',5760],['其它',1920]],orders:64,inquiries:100};
const metricPercent=(n,total)=>Math.round(n/total*100);
function metricSplit(title,items,money=false){const colors=['#627BFF','#FF8B62','#39C7B5','#FFC857'];return `<section class="metric-split"><h3>${title}</h3><div class="metric-track" role="img" aria-label="${items.map(([name,value])=>name+' '+value+(money?'元':'位')).join('，')}">${items.map(([name,value],i)=>`<span style="flex:${value};background:${colors[i]}"></span>`).join('')}</div><div class="metric-legend">${items.map(([name,value],i)=>`<div><i style="background:${colors[i]}"></i><span>${name}</span><b>${money?`¥${value.toLocaleString()}`:`${value} 位`}</b></div>`).join('')}</div></section>`}
function customerMetrics(){const d=businessMetrics;return `<div class="business-kpis"><div><span>客户总数</span><strong>${d.customers}<small>位</small></strong></div><div><span>客户转化率</span><strong>${metricPercent(d.convertedCustomers,d.customers)}<small>%</small></strong></div></div>${metricSplit('渠道占比',d.channels)}${metricSplit('客群分布',d.segments)}`}
function orderMetrics(){const d=businessMetrics,total=d.revenue.reduce((n,x)=>n+x[1],0);return `<div class="revenue-kpi"><span>本月营收</span><strong><small>¥</small>${total.toLocaleString()}</strong></div>${metricSplit('营收分布',d.revenue,true)}<div class="business-kpis order-kpis"><div><span>成交订单数</span><strong>${d.orders}<small>笔</small></strong></div><div><span>订单转化率</span><strong>${metricPercent(d.orders,d.inquiries)}<small>%</small></strong></div></div>`}
function businessReply(text){const d=businessMetrics,total=d.revenue.reduce((n,x)=>n+x[1],0);if(/黄小西|流失/.test(text))return `本月数据中，黄小西渠道有 ${d.channels[0][1]} 位客户，占客户总数的 50%。当前没有流失明细，暂时不能确定流失原因。\n\n建议先核对未成交客户的首次响应时间、报价后跟进、取消原因和服务反馈，再按“未响应、价格不匹配、行程变更、服务体验”分类，逐项排查。你可以补充一条客户记录，我们一起分析。`;if(/Q4|高客单|高复购/.test(text))return '按客户出行和消费记录，优先联系这 3 位高客单、高复购客户：\n\n1. 林女士｜近 12 个月出行 5 次，累计消费 ¥8,600；偏好亲子周末游，最近一次出行是 9 月 14 日。建议推荐 Q4 周末亲子路线。\n2. 陈志远｜近 12 个月出行 4 次，累计消费 ¥12,400；偏好商务接送，最近一次出行是 9 月 20 日。建议推荐固定用车方案。\n3. 王静怡｜近 12 个月出行 3 次，累计消费 ¥9,200；偏好定制游，最近一次出行是 8 月 28 日。建议推荐秋季短途路线。\n\n建议先向林女士发送：“您好，Q4 我们准备了适合亲子出行的周末路线。您近期有出游计划吗？告诉我人数和日期，我为您整理方案与报价。”\n\n以上是推荐名单和待发送话术，尚未向客户推送。';if(/下降|成交额/.test(text))return `本月营收为 ¥${total.toLocaleString()}，成交 ${d.orders} 笔，订单转化率 ${metricPercent(d.orders,d.inquiries)}%。目前缺少上月同期成交额及退款数据，不能确认下降幅度或原因。\n\n建议使用相同时间范围，依次比较有效询单量、订单转化率、平均客单价和退款金额；再拆分出行服务、佣金和其它收入。若询单减少，优先看渠道获客；若转化下降，检查响应和报价；若客单价下降，检查产品组合与折扣。`;if(/下月|增长机会/.test(text))return '结合当前营收结构，出行服务占营收 80%，佣金占 15%，其它占 5%。下月可优先验证三个增长方向：\n\n1. 企业客户：提前沟通商务接送与固定用车需求，争取连续订单。\n2. 高端、亲子客群：按预算和出行偏好组合定制路线，提高服务匹配度。\n3. 渠道转化：核对黄小西未成交线索，减少响应与跟进遗漏；向有意向的私域老客介绍 Q4 计划。\n\n先选一个客群小范围验证，每周记录询单、成交率、客单价和复购。当前数据不足以承诺增长幅度。';if(/复盘-客户/.test(text))return `本月客户总数 ${d.customers} 位，${d.convertedCustomers} 位已成交，客户转化率 40%。渠道占比为黄小西 50%、私域 35%、其它 15%；客群为企业 25%、高端 20%、亲子 35%、其它 20%。可以继续分析渠道流失或 Q4 客户经营计划。`;if(/复盘-订单/.test(text))return `本月营收 ¥${total.toLocaleString()}，成交 ${d.orders} 笔，订单转化率 64%。出行服务 ¥30,720、佣金 ¥5,760、其它 ¥1,920。可以继续讨论成交额变化或下月增长机会。`;return ''}

function homeTasks(){return activeTasks()}
function renderHomeIntro(){const intro=$('#home-intro');if(!intro)return;intro.innerHTML=`<div class="home-greeting"><p>杨师傅，早上好</p><h2>${activeTasks().length?`今日待办共 <span class="home-count">${activeTasks().length}</span> 项`:'暂时没有待办'}</h2></div>`}
function homeCard(t){const actions=taskActions(t);return `<div class="home-card-stack"><article class="task-card" data-id="${t.id}"><div class="home-card-top"><span class="home-task-symbol" style="--task-icon:url(icons/${t.icon}.svg)"><img src="icons/${t.icon}.svg" alt=""></span><span class="home-time">${esc(t.time)}</span></div><h2 class="task-title"><span>${esc(t.name)}</span></h2><div class="details">${t.id==='prepare'?'<p class="prep-intro">上传车辆照与个人照<br>确认车况、证照与随车物品</p>':`<div class="customer">${esc(t.customer)}${t.phone?`<a href="tel:${t.phone}">${esc(t.phone)}</a>`:''}</div><p class="route">${esc(t.from)} → ${esc(t.to)}</p>`}<p class="advice">${esc(t.flow?rideSteps[t.flowIndex].hint(t):t.advice)}</p></div><div class="actions">${actions.map(a=>`<button class="action primary" data-task="${t.id}" data-action="${esc(a)}" ${taskActionCompleted(t,a)?'disabled':''}><span>${esc(buttonLabel(a))}</span><img src="icons/arrow-up.svg" alt=""></button>`).join('')}</div></article></div>`}

// One continuous wheel or touch gesture turns at most one card.
const taskList=$('#task-list');
const turnTaskPage=(direction,index=Math.round(taskList.scrollTop/taskList.clientHeight))=>{const next=Math.max(0,Math.min(homeTasks().length-1,index+Math.sign(direction)));taskList.scrollTo({top:next*taskList.clientHeight,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})};
let flipWheelLocked=false,flipWheelTimer;
taskList.addEventListener('wheel',e=>{if(open||activeTab!=='home'||Math.abs(e.deltaY)<Math.abs(e.deltaX)||!e.deltaY)return;const card=e.target.closest('.task-card');if(card&&card.scrollHeight>card.clientHeight+2&&((e.deltaY>0&&card.scrollTop+card.clientHeight<card.scrollHeight-2)||(e.deltaY<0&&card.scrollTop>0)))return;e.preventDefault();clearTimeout(flipWheelTimer);flipWheelTimer=setTimeout(()=>{flipWheelLocked=false},150);if(flipWheelLocked)return;flipWheelLocked=true;turnTaskPage(e.deltaY)},{passive:false});
let taskSwipe=null;
taskList.addEventListener('touchstart',e=>{if(open||activeTab!=='home'||e.touches.length!==1)return;const touch=e.touches[0];taskSwipe={x:touch.clientX,y:touch.clientY,index:Math.round(taskList.scrollTop/taskList.clientHeight),card:e.target.closest('.task-card'),handled:false}},{passive:true});
taskList.addEventListener('touchmove',e=>{if(!taskSwipe||e.touches.length!==1)return;const touch=e.touches[0],dy=touch.clientY-taskSwipe.y,dx=touch.clientX-taskSwipe.x;if(Math.abs(dy)<5||Math.abs(dy)<Math.abs(dx))return;const card=taskSwipe.card,scrollDirection=-Math.sign(dy);if(card&&card.scrollHeight>card.clientHeight+2&&((scrollDirection>0&&card.scrollTop+card.clientHeight<card.scrollHeight-2)||(scrollDirection<0&&card.scrollTop>0))){taskSwipe=null;return}e.preventDefault();taskSwipe.handled=true},{passive:false});
taskList.addEventListener('touchend',e=>{if(!taskSwipe)return;const dy=(e.changedTouches[0]?.clientY??taskSwipe.y)-taskSwipe.y;if(taskSwipe.handled&&Math.abs(dy)>=70)turnTaskPage(-dy,taskSwipe.index);taskSwipe=null},{passive:true});
taskList.addEventListener('touchcancel',()=>{taskSwipe=null},{passive:true});
